sys_script_include.script:
var PelicanCaseAPI = Class.create();
PelicanCaseAPI.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    EQUIPMENT_CASE_CATEGORY: '14f99cf4471887507ed4bb30116d43ae',
    INSTALL_STATUS_RETIRED: '7',

    listCases: function() {
        var includeEmpty = this.getParameter('sysparm_include_empty') === 'true';
        var search = this.getParameter('sysparm_search') || '';

        var gr = new GlideRecord('alm_asset');
        gr.addQuery('model.cmdb_model_category', this.EQUIPMENT_CASE_CATEGORY);
        gr.addQuery('install_status', '!=', this.INSTALL_STATUS_RETIRED);
        if (search) {
            var qc = gr.addQuery('asset_tag', 'CONTAINS', search);
            qc.addOrCondition('display_name', 'CONTAINS', search);
            qc.addOrCondition('model.name', 'CONTAINS', search);
        }
        gr.orderBy('asset_tag');
        gr.query();

        var cases = [];
        while (gr.next()) {
            var caseId = gr.getUniqueValue();
            var count = this._countContents(caseId);
            if (!includeEmpty && count === 0) continue;
            cases.push({
                sys_id: caseId,
                asset_tag: gr.getValue('asset_tag') || '',
                display_name: gr.getDisplayValue('display_name'),
                model: gr.getDisplayValue('model'),
                location: gr.getDisplayValue('location'),
                install_status: gr.getDisplayValue('install_status'),
                content_count: count
            });
        }
        return JSON.stringify({ ok: true, cases: cases });
    },

    getCaseContents: function() {
        var caseId = this.getParameter('sysparm_case_id');
        if (!caseId) return this._err('case_id required');
        var search = this.getParameter('sysparm_search') || '';

        var gr = new GlideRecord('alm_asset');
        gr.addQuery('parent', caseId);
        gr.addQuery('install_status', '!=', this.INSTALL_STATUS_RETIRED);
        if (search) {
            var qc = gr.addQuery('asset_tag', 'CONTAINS', search);
            qc.addOrCondition('display_name', 'CONTAINS', search);
            qc.addOrCondition('model.name', 'CONTAINS', search);
        }
        gr.orderBy('display_name');
        gr.setLimit(500);
        gr.query();

        var assets = [];
        while (gr.next()) {
            assets.push({
                sys_id: gr.getUniqueValue(),
                asset_tag: gr.getValue('asset_tag') || '',
                display_name: gr.getDisplayValue('display_name'),
                model: gr.getDisplayValue('model'),
                serial_number: gr.getValue('serial_number') || ''
            });
        }
        return JSON.stringify({ ok: true, assets: assets, truncated: assets.length === 500 });
    },

    moveAssets: function() {
        var assetIdsRaw = this.getParameter('sysparm_asset_ids') || '';
        var targetCaseId = this.getParameter('sysparm_target_case_id') || '';

        var assetIds = assetIdsRaw.split(',').map(function(s) { return s.trim(); }).filter(function(s) { return s.length > 0; });
        if (assetIds.length === 0) return this._err('asset_ids required');

        if (targetCaseId) {
            var target = new GlideRecord('alm_asset');
            if (!target.get(targetCaseId)) return this._err('target case not found');
            var modelGr = new GlideRecord('cmdb_model');
            if (!modelGr.get(target.getValue('model'))) {
                return this._err('target has no model');
            }
            if (modelGr.getValue('cmdb_model_category') !== this.EQUIPMENT_CASE_CATEGORY) {
                return this._err('target is not an Equipment Case');
            }
        }

        var moved = 0;
        var errors = [];
        for (var i = 0; i < assetIds.length; i++) {
            var aid = assetIds[i];
            if (targetCaseId && aid === targetCaseId) {
                errors.push({ sys_id: aid, error: 'cannot move case into itself' });
                continue;
            }
            var a = new GlideRecord('alm_asset');
            if (!a.get(aid)) {
                errors.push({ sys_id: aid, error: 'asset not found' });
                continue;
            }
            a.parent = targetCaseId || '';
            if (a.update()) {
                moved++;
            } else {
                errors.push({ sys_id: aid, error: 'update failed' });
            }
        }

        return JSON.stringify({ ok: true, moved: moved, errors: errors });
    },

    _countContents: function(caseId) {
        var ga = new GlideAggregate('alm_asset');
        ga.addQuery('parent', caseId);
        ga.addQuery('install_status', '!=', this.INSTALL_STATUS_RETIRED);
        ga.addAggregate('COUNT');
        ga.query();
        if (ga.next()) {
            return parseInt(ga.getAggregate('COUNT'), 10) || 0;
        }
        return 0;
    },

    _err: function(msg) {
        return JSON.stringify({ ok: false, error: msg });
    },

    type: 'PelicanCaseAPI'
});
